function form(){const activeLot=lots.find(l=>l.id===activeId),m=calculateLot({...state,referenceDate:new Date().toISOString().slice(0,10)}),exitRows=state.exits||[],deaths=exitRows.length?exitRows.filter(x=>x.type==='morte'&&x.confirmed!==false).reduce((s,x)=>s+safe(x.quantity),0):safe(state.deaths),otherExits=exitRows.length?exitRows.filter(x=>x.type==='outra'&&x.confirmed!==false).reduce((s,x)=>s+safe(x.quantity),0):safe(state.otherExits),currentAnimals=Math.max(0,safe(state.animals)-deaths-otherExits),mortality=safe(state.animals)?deaths/safe(state.animals)*100:0;return `<div class="page"><div class="form-intro"><div><h2>Premissas do ciclo</h2><p>Edite os dados; os indicadores são recalculados.</p></div></div><section class="form-panel"><div class="section-title"><span>01</span><div><h3>Dados do lote</h3><p>Informações zootécnicas</p></div></div><div class="form-grid">${field('Nome do lote','name')}${field('Animais de entrada','animals','cabeças')}${field('Peso médio de entrada','entryWeight','kg')}${field('Peso atual / saída','currentWeight','kg')}${field('Dias no sistema','days','dias')}${field('Rendimento de carcaça','carcassYield','%')}</div><div class="movement-box"><div class="section-title"><div><h3>Baixas por dia do ciclo</h3><p>Registre mortes e outras saídas para ajustar animais-dia e nutrição.</p></div><button id="add-exit" class="secondary-btn">+ Registrar baixa</button></div>${exitRows.length?exitRows.map((x,i)=>'<div class="form-grid"><label><span>Tipo</span><select data-exit-type="'+i+'" '+(x.confirmed?'disabled':'')+'><option value="morte" '+(x.type==='morte'?'selected':'')+'>Morte</option><option value="outra" '+(x.type==='outra'?'selected':'')+'>Outra saída</option></select></label><label><span>Quantidade</span><input type="number" min="1" value="'+x.quantity+'" data-exit-qty="'+i+'" '+(x.confirmed?'disabled':'')+'></label><label><span>Data da baixa</span><input type="date" value="'+(x.date||'')+'" data-exit-date="'+i+'" '+(x.confirmed?'disabled':'')+'></label><label><span>Foto do animal (opcional)</span><input type="file" accept="image/*" data-exit-photo="'+i+'" '+(x.confirmed?'disabled':'')+'><small>'+(x.photoName||'')+'</small></label><label><span>Motivo / observação</span><input type="text" placeholder="Ex.: acidente ofídico, clostridiose..." value="'+(x.observation||'')+'" data-exit-observation="'+i+'" '+(x.confirmed?'disabled':'')+'></label>'+(x.confirmed?'<b>✓ Baixa confirmada</b>':'<button class="primary-btn" data-confirm-exit="'+i+'">Confirmar baixa</button>')+'<button class="secondary-btn" data-remove-exit="'+i+'">Remover</button></div>').join(''):'<p>Nenhuma baixa por dia registrada.</p>'}</div><div class="movement-box"><h3>Custo de nutrição do lote</h3><p>Veja quanto custa alimentar os animais durante o período informado e como as baixas alteram esse valor.</p><div class="summary-strip"><span><small>Animais de entrada</small><b>${num(state.animals,0)} cabeças</b></span><span><small>Período considerado</small><b>${num(state.days,0)} dias</b></span><span><small>Animais atuais</small><b>${num(currentAnimals,0)} cabeças</b></span></div><div class="summary-strip"><span><small>Custo previsto sem baixas</small><b>${brl(safe(state.animals)*safe(state.days)*safe(state.intake)*safe(state.dietCost))}</b></span><span><small>Redução do custo após as baixas</small><b>${brl(Math.max(0,safe(state.animals)*safe(state.days)*safe(state.intake)*safe(state.dietCost)-m.feedTotal))}</b></span><span><small>Custo de nutrição ajustado</small><b>${brl(m.feedTotal)}</b></span></div><p><small>O ajuste considera a data de cada baixa confirmada. O custo de compra dos animais continua incluído no resultado financeiro.</small></p></div><div class="summary-strip"><span><small>Animais atuais</small><b>${num(currentAnimals,0)} cabeças</b></span><span><small>Mortalidade</small><b>${num(mortality,2)}%</b></span><span><small>Total de baixas</small><b>${num(deaths+otherExits,0)} cabeças</b></span></div><div class="calculated"><span>↗ GMD calculado</span><b>${num(m.dailyGain,2)} kg/dia</b><small>Ganho: ${num(m.gain)} kg · ${num(m.liveArrobasProducedPerAnimal,2)} @ eq. PV/animal</small></div><div class="summary-strip"><span><small>@ produzida equivalente (PV)</small><b>${num(m.liveArrobasProducedPerAnimal,2)} @/animal</b></span><span><small>Peso de carcaça projetado</small><b>${num(m.carcassWeightPerAnimal,1)} kg/animal</b></span><span><small>@ de carcaça na saída</small><b>${num(m.carcassArrobasPerAnimal,2)} @/animal</b></span></div></section><section class="form-panel"><div class="section-title"><span>02</span><div><h3>Compra, nutrição e venda</h3><p>Premissas econômicas</p></div></div><div class="form-grid">${field('Peso de compra','purchaseWeight','kg')}${unitSelect('Unidade do preço de compra','purchaseUnit',[['kg','Por kg'],['arroba','Por arroba (@)']])}${field('Preço de compra','purchasePrice',state.purchaseUnit==='kg'?'R$/kg':'R$/@')}${unitSelect('Unidade do preço de venda','saleUnit',[['kg','Por kg'],['arroba','Por arroba (@)']])}${field('Preço esperado de venda','salePrice',state.saleUnit==='kg'?'R$/kg':'R$/@')}${field('Consumo de matéria natural','intake','kg/animal/dia')}${field('Custo da dieta','dietCost','R$/kg')}</div><div class="summary-strip"><span><small>Compra total</small><b>${brl(m.purchaseTotal)}</b></span><span><small>Nutrição do lote</small><b>${brl(m.feedTotal)}</b></span><span><small>Receita projetada</small><b>${brl(m.revenue)}</b></span></div><div class="preview-form-actions"><button data-page="dashboard">Ver dashboard atualizado</button></div></section><section class="form-panel"><div class="section-title"><span>03</span><div><h3>Custos operacionais</h3><p>Sanidade, mão de obra, fretes, comissões e outras despesas</p></div></div><div class="cost-list">${state.otherCosts.map(costField).join('')}</div></section></div>`}
function actualMetrics(item){const a=item.actual;if(!a)return null;const base=item.projection||item.data,actualData={...JSON.parse(JSON.stringify(base)),currentWeight:a.saleWeight,days:a.days,carcassYield:a.carcassYield,intake:a.intake,dietCost:a.dietCost,salePrice:a.salePrice,saleUnit:a.saleUnit},calc=calculateLot(actualData),investment=calc.investment+safe(a.extraCosts),result=calc.revenue-investment;return {...calc,investment,result,roi:investment?result/investment*100:0,marginPerAnimal:actualData.animals?result/actualData.animals:0}}
function lotsPage(){return `<div class="page"><div class="form-intro"><div><h2>Lotes e ciclos</h2><p>Cadastre, acompanhe e finalize os ciclos da propriedade.</p></div><button id="new-lot" class="primary-btn">+ Novo lote</button></div><div class="lots-grid">${lots.map((item,i)=>{const m=calculateLot(item.data);const ex=(item.data.exits||[]).filter(x=>x.confirmed!==false&&safe(x.quantity)>0),baixas=ex.length?ex.reduce((n,x)=>n+safe(x.quantity),0):safe(item.data.deaths)+safe(item.data.otherExits);return `<article class="lot-card"><div class="lot-card-head"><div><span class="lot-status ${item.status}">${item.status==='ativo'?'Ativo':'Finalizado'}</span><h3>${item.data.name}</h3></div><b>${Math.max(0,safe(item.data.animals)-baixas)} atuais / ${item.data.animals} entrada</b></div><div class="lot-kpis"><span><small>GMD</small><b>${num(m.dailyGain,2)} kg/dia</b></span><span><small>Dias</small><b>${item.data.days}</b></span><span><small>Resultado</small><b>${brl(m.result)}</b></span><span><small>ROI</small><b>${num(m.roi,2)}%</b></span></div><div class="lot-actions"><button data-open-lot="${i}">Abrir dashboard</button>${item.status==='ativo'?'<button data-edit-lot="'+i+'">Editar</button>':''}<button class="secondary-btn" data-status-lot="${i}">${item.status==='ativo'?'Finalizar ciclo':'Reabrir ciclo'}</button></div></article>`}).join('')}</div></div>`}
